    for cand in slot["candidates"]:
        x[(sid, cand["product_id"])] = model.addVar(vtype=GRB.BINARY, name=f"x_{sid}_{cand['product_id']}")

model.setObjective(
    gp.quicksum(
        x[(slot["slot_id"], cand["product_id"])] * cand["price"] * slot["quantity"]
        for slot in slots
        for cand in slot["candidates"]
    ),
    GRB.MINIMIZE
)

